// Store stock (the catalog row's `inventory`) vs the quantity on a basket line. DC, Nov 14:
//   "If the customer asks explicitly a quantity for a certain product, e.g. i need 50 bottles of Titos - 750 ML, then tell
//    the customer that exact product has only x so you can offer something similar. If the customer doesn't ask for a
//    product explicitly with the desired quantity, it should only offer products that meet the quantity requirements
//    either asked by the customer or generated by the recommendation engines."
// Until then nothing read `inventory`: a line could ask the store for 50 when it had 41.
//
// inv(row)            -> the count, or null = unknown (missing / not a number / ignored as a placeholder)
// enough(row, qty)    -> true when the store can supply qty (unknown counts as enough — never block on missing data)
// ignorePlaceholders(rows, term) -> rows; a search whose rows (10+) ALL show the same count is a placeholder, not stock
//                        (Nov 14: every Boston 02110 tequila row said 10) — the counts are dropped, logged.
// similar(line, rows, need, opts) -> same type + size products that can supply `need`, closest price first
// enforce(lines, { rowFor, search, log }) -> { lines, short: [...], swaps: [...] }  (buildPackage's last step)
//   line.match.kind === 'exact' (a product the customer named): kept at what the store has, reported in `short` with up
//     to 3 similar products that can cover the rest — never swapped behind the customer's back.
//   any other line (Rachel's pick: generic slot, stand-in, closest match): replaced by a similar product that covers the
//     WHOLE quantity; none -> split across similar products; Mi Campo (the house tequila) is split, never swapped away.

const DT = require('./drink-type.js');
const SM = require('./search-match.js');

function inv(row) {
  if (!row || row.inventory === null || row.inventory === undefined || row.inventory === '') return null;
  const n = Number(row.inventory);
  return Number.isFinite(n) ? Math.max(0, Math.floor(n)) : null;
}
const enough = (row, qty) => { const n = inv(row); return n === null || n >= (Number(qty) || 1); };

// Per store: a store whose in-stock rows (10+ in one search) all show the same count reports a placeholder (Boston 02110:
// every in-stock row says 10, an out-of-stock one 0). Remembered per establishmentId (RACHEL_DATA_DIR/stock-placeholder-
// stores.json) so a small search of that store is read the same way: the placeholder = unknown, 0 = out of stock (kept).
const fs = require('fs');
let FLAT = null;
const flatFile = () => { try { return require('./data-dir.js').file('stock-placeholder-stores.json'); } catch (e) { return ''; } };
function flat() {
  if (FLAT) return FLAT;
  try { FLAT = JSON.parse(fs.readFileSync(flatFile(), 'utf8')) || {}; } catch (e) { FLAT = {}; }
  return FLAT;
}
const isPlaceholderStore = est => flat()[est || ''] !== undefined;
function ignorePlaceholders(rows, term) {
  if (!Array.isArray(rows) || !rows.length) return rows;
  const F = flat(), byStore = {};
  for (const r of rows) if (r && typeof r.inventory === 'number' && r.inventory > 0) (byStore[r.establishmentId || ''] = byStore[r.establishmentId || ''] || []).push(r.inventory);
  for (const [est, vals] of Object.entries(byStore)) {
    if (vals.length >= 10 && vals.every(v => v === vals[0]) && F[est] !== vals[0]) {
      F[est] = vals[0];
      console.log('[stock] store ' + (est || '?') + ': every in-stock row of ' + JSON.stringify(String(term || '')).slice(0, 60) + ' (' + vals.length + ') shows ' + vals[0] + ' — a placeholder, its counts are read as unknown (0 = out of stock)');
      try { if (flatFile()) fs.writeFileSync(flatFile(), JSON.stringify(F, null, 1)); } catch (e) {}
    }
  }
  if (!rows.some(r => r && F[r.establishmentId || ''] !== undefined && r.inventory === F[r.establishmentId || ''])) return rows;
  return rows.map(r => r && F[r.establishmentId || ''] !== undefined && r.inventory === F[r.establishmentId || ''] ? Object.assign({}, r, { inventory: null }) : r);
}

const nz = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
function sizeKey(p) {
  const t = String((p && p.name) || '') + ' ' + String((p && (p.sizeStr || p.size)) || '');
  const pk = t.toLowerCase().match(/(\d+)\s*x\s*(\d+(?:\.\d+)?)\s*(ml|l|oz)\b/);
  if (pk) return pk[1] + 'x' + pk[2] + pk[3];
  const m = t.toLowerCase().match(/(\d+(?:\.\d+)?)\s*(ml|l|liters?|litres?|oz)\b/);
  if (!m) return '';
  const v = +m[1], u = m[2];
  return /^l/.test(u) ? String(v * 1000) + 'ml' : u === 'oz' ? v + 'oz' : v + 'ml';
}
const kindOf = p => DT.typeOf(p) || String((p && (p.subCategory || p.subcategory || p.category)) || '').toLowerCase();
// What to search for products like this one.
function termFor(p) {
  const t = DT.typeOf(p);
  if (t) return DT.searchTerm(t);
  return String((p && (p.subCategory || p.subcategory)) || (p && p.category) || '').trim() || String((p && p.name) || '').split(/\s+/).slice(0, 2).join(' ');
}

// rows -> those that can stand in for `line` (same kind + size, alcoholic-ness, not the line itself) and supply `need`,
// a known count first, then the closest price. opts.knownOnly: unknown counts are left out.
function similar(line, rows, need, opts = {}) {
  const k = kindOf(line), sz = sizeKey(line), price = Number(line.price) || 0, na = DT.isNA(line);
  const skip = new Set([nz(line.name)].concat((opts.exclude || []).map(nz)));
  const seen = new Set();
  return (rows || []).filter(r => {
    if (!r || !r.name || skip.has(nz(r.name)) || seen.has(nz(r.name))) return false;
    seen.add(nz(r.name));
    if (k && kindOf(r) !== k) return false;
    if (sz && sizeKey(r) !== sz) return false;
    if (DT.isNA(r) !== na) return false;
    if (FLAV.test(String(r.name || '')) && !FLAV.test(String(line.name || ''))) return false;
    { const lf = flavours(line.name); if (lf.length && !lf.every(w => flavours(r.name).includes(w))) return false; }   // grapefruit stays grapefruit
    // A grape the line names must be on the stand-in's label too (a Pinot Noir is never "similar" to a Cabernet or a Rioja).
    if (SM.grapesOf(String(line.name || '')).length && (!SM.grapesOf(String(r.name || '')).length || !SM.carriesGrapes(String(line.name || ''), String(r.name || '')))) return false;   // plain Tito's -> never a pineapple vodka
    const rp = Number(r.price) || 0;
    if (!(rp > 0) || (price > 0 && (rp < price * 0.5 || rp > price * 1.6))) return false;
    if (opts.knownOnly && inv(r) === null) return false;
    return enough(r, need);
  }).sort((a, b) => ((inv(a) === null) - (inv(b) === null)) || Math.abs((+a.price || 0) - price) - Math.abs((+b.price || 0) - price));
}

const FLAV = /\b(coconut|vanilla|citrus|citron|mandrin|mandarin|peach|mango|pineapple|berry|raspberry|strawberry|cherry|apple|pear|apricot|melon|banana|pomegranate|grapefruit|cucumber|elderflower|hibiscus|lemon|lime|orange|grape|watermelon|passion|honey|cinnamon|pepper|jalapen|chocolate|espresso|coffee|caramel|botanical|flavou?red|spiced)\b/i;
const flavours = n => (String(n || '').toLowerCase().match(new RegExp(FLAV.source, 'gi')) || []).filter(w => !/^(flavou?red|botanical|spiced)$/.test(w));
const asLine = (line, r, qty) => Object.assign({}, line, { name: r.name, price: Number(r.price) || 0, size: r.sizeStr || r.size || line.size, url: r.url || '', product_id: r.product_id || '', upc: r.upc || '', establishmentId: r.establishmentId || line.establishmentId || '', qty, quantity: undefined });

async function enforce(lines, { rowFor, search }) {
  const out = [], short = [], swaps = [];
  for (const li of lines || []) {
    const row = rowFor(li), have = inv(row), qty = Number(li.qty) || 1;
    if (have === null || have >= qty) { out.push(li); continue; }
    const rows = await search(termFor(Object.assign({}, row, li))).catch(() => []);
    // The customer named this product AND gave its quantity (DC: "asks explicitly a quantity for a certain product") — a
    // product Rachel put on a list herself (a cocktail's spirit, an event line) is her pick, even when matched exactly.
    // "3 bottles Pinot Noir" is generic (no producer / brand words in what the customer wrote): the bottle is Rachel's pick.
    const named = !!(li.match && li.match.kind === 'exact' && li.customer_qty && SM.keyOf(String(li.label || li.name || '')).length);
    if (named) {
      // The customer's own product: what the store has, and similar products for the rest.
      const need = qty - have;
      // Offered as covering the rest: a known count — except at a store that only reports placeholders, where a listed
      // product not at 0 is the best there is.
      const opts = similar(Object.assign({}, row, li), rows, need, { knownOnly: !isPlaceholderStore(li.establishmentId || (row && row.establishmentId)) }).slice(0, 3);
      console.log('[stock] SHORT (named): ' + li.name + ' — asked ' + qty + ', the store has ' + have + (have ? ' -> ' + have + ' kept' : ' -> line removed') + '; similar for the other ' + need + ': ' + (opts.map(o => o.name + ' (' + (inv(o) === null ? '?' : inv(o)) + ')').join(', ') || 'none'));
      if (have > 0) out.push(Object.assign({}, li, { qty: have, stock_short: { asked: qty, available: have } }));
      short.push({ label: li.label || li.name, name: li.name, size: li.size || '', asked: qty, available: have, need, category: li.category || '',
        similar: opts.map(o => ({ name: o.name, price: Number(o.price) || 0, size: o.sizeStr || '', url: o.url || '', product_id: o.product_id || '', upc: o.upc || '', establishmentId: o.establishmentId || '', inventory: inv(o) })) });
      continue;
    }
    // Rachel's pick: one product that covers the whole quantity, else split across similar products.
    const whole = /mi campo/i.test(li.name) ? [] : similar(Object.assign({}, row, li), rows, qty);
    if (whole.length) {
      const r = whole[0];
      console.log('[stock] SWAPPED: ' + li.name + ' has ' + have + ' (needed ' + qty + ') -> ' + r.name + ' (' + (inv(r) === null ? 'count unknown' : inv(r) + ' in stock') + ')');
      swaps.push({ from: li.name, to: r.name, qty, had: have });
      const nl = asLine(li, r, qty); delete nl.quantity;
      if (nl.match && nl.match.kind !== 'exact') nl.match = Object.assign({}, nl.match, { note: (nl.match.note ? nl.match.note + '; ' : '') + li.name + ' had only ' + have + ' in stock' });
      out.push(nl);
      continue;
    }
    let left = qty;
    const parts = [];
    if (have > 0) { parts.push(Object.assign({}, li, { qty: have })); left -= have; }
    for (const r of similar(Object.assign({}, row, li), rows, 1, { exclude: [li.name] })) {
      if (left <= 0) break;
      const take = inv(r) === null ? left : Math.min(left, inv(r));
      if (take <= 0) continue;
      const nl = asLine(li, r, take); delete nl.quantity; parts.push(nl); left -= take;
    }
    if (left > 0) {
      // Not enough anywhere: keep what there is and say so (the line is never left asking for more than the store has).
      console.log('[stock] SHORT (pick): ' + li.name + ' — needed ' + qty + ', only ' + (qty - left) + ' across similar products in stock');
      short.push({ label: li.label || li.name, name: li.name, size: li.size || '', asked: qty, available: qty - left, need: left, category: li.category || '', similar: [], pick: true });
    }
    if (parts.length > 1) { console.log('[stock] SPLIT: ' + li.name + ' (' + have + ' in stock, needed ' + qty + ') -> ' + parts.map(p => p.qty + 'x ' + p.name).join(' + ')); swaps.push({ from: li.name, to: parts.slice(1).map(p => p.name).join(', '), qty, had: have, split: true }); }
    out.push(...parts);
  }
  return { lines: out, short, swaps };
}

// The customer-facing note for `short` (appended in code on /chat; given as stock_note on the connector).
function noteFor(short) {
  if (!short || !short.length) return '';
  return short.map(s => {
    const what = s.name + (s.size && nz(s.name).indexOf(nz(s.size)) < 0 ? ' ' + s.size : '');
    if (s.pick) return s.available > 0
      ? 'Heads-up: the store has only ' + s.available + ' of the ' + s.asked + ' needed for ' + (s.label || what) + ' in stock right now (' + what + ' and similar), so the package has ' + s.available + '.'
      : 'Heads-up: ' + (s.label || what) + ' — nothing that fits is in stock at this store right now, so it isn\'t in the package.';
    const head = s.available > 0
      ? what + ': the store has only ' + s.available + ' in stock (you asked for ' + s.asked + '), so I put ' + s.available + ' in your cart.'
      : what + ': the store has none in stock right now (you asked for ' + s.asked + '), so it is not in your cart.';
    if (!s.similar.length) return head + ' I found nothing similar with ' + s.need + ' in stock.';
    return head + ' For the other ' + s.need + ', similar ones in stock:\n' + s.similar.map((o, i) => (i + 1) + '. ' + o.name + ' — $' + Number(o.price).toFixed(2)).join('\n')
      + '\nReply with a number and I\'ll add ' + s.need + ' of it.';
  }).join('\n\n');
}

// A raw catalog row (salePrice, size + units) in the shape similar() reads.
const rowOf = p => ({ name: p.name || '', price: Number(p.salePrice || p.price) || 0, sizeStr: p.sizeStr || (p.size && p.units ? p.size + ' ' + p.units : String(p.size || '')),
  category: p.category || '', subCategory: p.subCategory || p.subcategory || '', inventory: inv(p), url: p.url || '', product_id: (p.corpProductFilter && p.corpProductFilter.corpProductId) || p.product_id || p.id || '',
  upc: p.upc || '', establishmentId: p.establishmentId || '', _raw: p });

module.exports = { isPlaceholderStore, inv, enough, ignorePlaceholders, similar, enforce, noteFor, sizeKey, termFor, rowOf };
